// Count how often each word appears in a text.
export function wordFreq(text) {
  const counts = {}
  for (const word of text.split(' ')) {
    if (!word) continue
    counts[word] = (counts[word] || 0) + 1
  }
  return counts
}

export function topWords(text, n = 3) {
  return Object.entries(wordFreq(text))
    .sort((a, b) => b[1] - a[1])
    .slice(0, n)
    .map(([word]) => word)
}

